import { Image } from "expo-image";
import { View } from "react-native";

import { cn } from "@/lib/cn";

// Generated by scripts/generate-wordmark.py (League Spartan Bold + custom rounded "r", ink).
// Metro picks @2x/@3x automatically.
const source = require("@/assets/images/brand/wordmark.png");
// Intrinsic to the asset (693×144 @3x), not a design token.
const ASPECT_RATIO = 693 / 144;

const sizes = {
  sm: "h-wordmark-sm", // 16: auth header
  md: "h-wordmark-md", // 28: onboarding
  home: "h-wordmark-home", // 34: home header
  lg: "h-wordmark-lg", // 48: brand lockup
} as const;

export type WordmarkProps = {
  size?: keyof typeof sizes;
  /** Layout only. */
  className?: string;
};

/** The roam wordmark. Height comes from spacing tokens; width follows the asset's aspect ratio. */
export function Wordmark({ size = "md", className }: WordmarkProps) {
  return (
    <View
      accessible
      accessibilityRole="image"
      accessibilityLabel="roam"
      // self-start: width comes from height × the asset's aspect ratio, never from the parent.
      className={cn("self-start", sizes[size], className)}
      style={{ aspectRatio: ASPECT_RATIO }}
    >
      <Image source={source} contentFit="contain" style={{ width: "100%", height: "100%" }} />
    </View>
  );
}
